{"code":"import pandas as pd
import ast

def processing(dfs):
    df = dfs[0]
    # Parse the 'payload' column
    # Using ast.literal_eval because it's a string representation of a Python dict
    data = [ast.literal_eval(p) for p in df['payload']]
    df_parsed = pd.DataFrame(data)

    # Unify columns
    def get_amount(row):
        if pd.notna(row.get('amount_cents')):
            return row.get('amount_cents') / 100.0
        return row.get('amount')

    def get_currency(row):
        val = row.get('currency_code')
        if pd.notna(val):
            return val
        return row.get('currency')

    def get_status(row):
        val = row.get('state')
        if pd.notna(val):
            return val
        return row.get('status')

    df_parsed['combined_amount'] = df_parsed.apply(get_amount, axis=1)
    df_parsed['combined_currency'] = df_parsed.apply(get_currency, axis=1)
    df_parsed['combined_status'] = df_parsed.apply(get_status, axis=1)

    # Filter
    # Status and currency codes are case-insensitive
    mask = (df_parsed['combined_status'].str.lower() == 'succeeded') & \
           (df_parsed['combined_currency'].str.lower() == 'usd')

    result = df_parsed[mask]['combined_amount'].max()

    return pd.DataFrame({'max_succeeded_usd_amount': [result]})

# Test
conn.execute("SELECT * FROM payment_events")
df_raw = pd.read_sql_query("SELECT payload FROM payment_events", conn)
print(processing([df_raw]))
"}

