        CAST(json_extract(payload, '$.amount_cents') AS FLOAT) / 100.0,
        CAST(json_extract(payload, '$.amount') AS FLOAT)
    )
)
FROM payment_events
WHERE LOWER(COALESCE(json_extract(payload, '$.state'), json_extract(payload, '$.status'))) = 'succeeded'
